    pub(super) fn routing168_fixture(
        count: usize,
    ) -> (
        Arc<Mutex<DaemonState>>,
        DaemonConfig,
        Receiver<ManagedSupervisorCommand>,
        BufReader<UnixStream>,
        AutoDelegateV2,
        PathBuf,
    ) {
        let (mut st, config, rx, reader) = fixture("r168");
        let root = st.fixture_root.as_ref().unwrap().0.clone();
        let cwd = root.join("source168");
        std::fs::create_dir(&cwd).unwrap();
        std::fs::set_permissions(&cwd, std::fs::Permissions::from_mode(0o700)).unwrap();
        let models = (0..count)
            .map(|index| format!("m{index:03}"))
            .collect::<Vec<_>>();
        let caps = models
            .iter()
            .map(|model| (model.clone(), json!({"efforts":["low","high"]})))
            .collect::<serde_json::Map<_, _>>();
        let catalog = models
            .iter()
            .map(|model| {
                json!({"model":model,"supported_efforts":["low","high"],
            "default_effort":"high","provenance":"operator_observation"})
            })
            .collect::<Vec<_>>();
        let value = json!({
            "agents":{"native-test":{"command":"/bin/sh","args":["app-server"],"protocol":"codex_app_server",
                "forbidden_env":[],"capabilities":{"execution_paths":["codex_app_server"],"models":caps}}},
            "routing_policy":{"version":2,"revision":1,"enabled":true,
                "connections":[{"connection_id":"main","machine_id":"local","engine":"codex",
                    "agent_type":"native-test","enabled":true}],
                "model_catalog":{"main":catalog},
                "machine_policies":{"local":{"enabled":true,"compilation_capacity":3,
                    "decision_timeout_ms":10000,"service_timeout_ms":2000}}}
        });
        let path = root.join("routing168.json");
        std::fs::write(&path, value.to_string()).unwrap();
        std::fs::set_permissions(&path, std::fs::Permissions::from_mode(0o600)).unwrap();
        st.registry = AgentRegistry::load_from_path(path).unwrap();
        st.source_env
            .insert("HOME".into(), root.clone().into_os_string());
        st.source_env.insert("PATH".into(), "/usr/bin:/bin".into());
        st.native_permission_facts.insert("conn-1".into(),(bridget_transport::protocol::ProviderPermissions {
            version:1,source:"native_wrapper".into(),run_id:"run168".into(),
            provider_session_id:"session168".into(),provider_instance_id:"instance-1".into(),
            revision:1,driver:"codex_app_server".into(),cwd:cwd.to_string_lossy().into_owned(),
            runtime_mode:"full-access".into(),interaction_mode:"default".into(),
            provider_policy:json!({"kind":"codex","approval_policy":"never","approvals_reviewer":"user",
                "sandbox_policy":{"type":"dangerFullAccess"}}),
        },None));
        let request: AutoDelegateV2 = serde_json::from_value(json!({"request_id":"route168",
            "task":"Compiler le composant demandé","cwd":cwd,"posture":"discovery"}))
        .unwrap();
        (Arc::new(Mutex::new(st)), config, rx, reader, request, root)
    }

    fn routing168_update(state: &Arc<Mutex<DaemonState>>, change: impl FnOnce(&mut Value)) {
        let mut st = state.lock().unwrap();
        let path = st.registry.source().to_owned();
        let mut value: Value = serde_json::from_slice(&std::fs::read(&path).unwrap()).unwrap();
        change(&mut value);
        std::fs::write(&path, value.to_string()).unwrap();
        st.registry = AgentRegistry::load_from_path(path).unwrap();
    }

    #[test]
    fn spec172_routing_connection_scope_changes_only_with_declared_account_authority() {
        let (state, config, _rx, _reader, _request, _root) = routing168_fixture(1);
        let scope = state
            .lock()
            .unwrap()
            .registry
            .routing_connection_scope("main")
            .unwrap();
        assert!(
            state
                .lock()
                .unwrap()
                .registry
                .routing_connection_scope("absent")
                .is_none()
        );
        // Une sélection de modèle de mission ne modifie pas le registre du compte.
        let _candidates = state.lock().unwrap().registry.routing_candidates().unwrap();
        assert_eq!(
            state
                .lock()
                .unwrap()
                .registry
                .routing_connection_scope("main")
                .unwrap(),
            scope
        );
        routing168_update(&state, |value| {
            value["routing_policy"]["revision"] = json!(2)
        });
        let revised = state
            .lock()
            .unwrap()
            .registry
            .routing_connection_scope("main")
            .unwrap();
        assert_ne!(revised, scope);
        routing168_update(&state, |value| {
            value["agents"]["native-test"]["args"] = json!(["changed-account"])
        });
        assert_ne!(
            state
                .lock()
                .unwrap()
                .registry
                .routing_connection_scope("main")
                .unwrap(),
            revised
        );
        drop(state);
        cleanup(&config);
    }

    pub(super) fn routing168_plan(
        state: &Arc<Mutex<DaemonState>>,
        request: &AutoDelegateV2,
    ) -> RoutingAdmissionPlan {
        let st = state.lock().unwrap();
        routing_admission_plan(&st.registry, "local", request).unwrap()
    }

    #[test]
    fn spec221_c14_two_eligible_exclude_denied_before_frozen_decision() {
        use bridget_transport::protocol::*;
        let (state, config, rx, _reader, mut request, root) = routing168_fixture(3);
        {
            let mut st=state.lock().unwrap();
            st.host="coordinator171".into();
            st.presences.get_mut("instance-1").unwrap().host="coordinator171".into();
        }
        request.request_id = "c14-mixed221".into();
        request.project_id = Some("project171".into());
        request.machine_id = Some("cartae".into());
        request.engine = Some("codex".into());
        let host = state.lock().unwrap().host.clone();
        let fingerprint = format!("{:x}", sha2::Sha256::digest(b"worker171-fixture"));
        routing168_update(&state, |value| {
            value["routing_policy"]["connections"][0]["machine_id"] = json!("cartae");
            value["routing_policy"]["machine_policies"]["cartae"] = json!({"enabled":true});
            value["machines"] = json!({"cartae":{"enabled":true,"worker_id":"worker171",
                "provisioning_revision":1,"credential_fingerprint":fingerprint,
                "allowed_agent_types":["native-test"],"mappings":{"project171":{
                    "source_host":host,"source_root":request.cwd,
                    "remote_root":root.join("remote171"),"expected_git_identity":"fixture171",
                    "mapping_revision":1}}}});
        });
        let (writer, mut reader) = super::super::presence_tests::control_socket("probe171-refused");
        {
            let mut st = state.lock().unwrap();
            st.connections.insert("worker171".into(), writer);
            st.peer_uids.insert("worker171".into(), bridget_transport::fsutil::effective_uid());
        }
        assert!(matches!(handle_worker_message(&state, "worker171",
            WrapperToDaemon::WorkerHelloWithCapabilities { hello: WorkerHelloWithCapabilities {
                hello: WorkerHello { version: REMOTE_WORKER_VERSION,
                    identity: WorkerIdentity { machine_id:"cartae".into(),
                        worker_id:"worker171".into(),provisioning_revision:1 },
                    credential: IdentityCredential::new("worker171-fixture".into()),
                    build:"fixture171".into(),capability:ClientCapability::RemoteWorkerV1 },
                capabilities:vec![WorkerCapability::CandidateProbeV2] } }),
            Some(DaemonToWrapper::WorkerAcceptedWithCapabilities { .. })));
        let responder_state=Arc::clone(&state);
        let responder=std::thread::spawn(move || {
            let DaemonToWrapper::CandidateProbeV2 {probe}=
                super::super::presence_tests::read_control(&mut reader)
                else {panic!("sonde attendue")};
            assert_eq!(probe.candidates.len(),3);
            let now=unix_timestamp();
            let verdicts=probe.candidates.into_iter().enumerate().map(|(index,c)| {
                if index==1 { CandidateProbeV2Verdict::Ineligible {
                    candidate_id:c.candidate_id,reason:CandidateProbeRefusal::PermissionsChanged
                }} else { CandidateProbeV2Verdict::Eligible {
                    candidate_id:c.candidate_id,mapping_revision:1,
                    definition_digest:"a".repeat(64),permission_digest:"b".repeat(64),observed_at:now
                }}
            }).collect();
            let result=CandidateProbeV2Result { tool_observations:Vec::new(),
                version:WORKER_CANDIDATE_PROBE_V2_VERSION,correlation_id:probe.correlation_id,
                connection_epoch:probe.connection_epoch,worker:probe.worker,
                admission_id:probe.admission_id,policy_revision:probe.policy_revision,
                resources:HostResourceSnapshotV1 {source_observed_at:now,received_at:now,
                    cpu_percent:None,available_memory_percent:None,
                    normalized_load_percent:None,compilation_slots:None},
                verdicts,
            };
            assert!(handle_worker_message(&responder_state,"worker171",
                WrapperToDaemon::CandidateProbeResultV2 {result}).is_none());
        });
        let canonical=serde_json::to_vec(&NativeDelegationRequest::AutoDelegateV2(request.clone())).unwrap();
        let mut plan=routing168_plan(&state,&request);
        observe_routing_candidates("conn-1",&request,&mut plan,None,&state).unwrap();
        responder.join().unwrap();
        assert_eq!(plan.candidates.iter().map(|c|c.model.as_str()).collect::<Vec<_>>(),["m000","m002"]);
        assert_eq!(plan.observations.len(),2);
        let note:Value=serde_json::from_str(&plan.decision_notes[0]).unwrap();
        assert_eq!(note["code"],"permissions_changed");
        let receipt=routing_auto_receipt(OWNER.into(),&request,canonical.clone(),&plan,
            state.lock().unwrap().coordinator_epoch,unix_timestamp()).unwrap();
        let decision=routing_decision_request(&request,&receipt,&plan).unwrap();
        assert_eq!(decision.candidates.len(),2);
        assert!(decision.candidates.iter().all(|c|c.model!="m001"));
        assert!(decision.machines.iter().all(|m|m.summary.contains("score(")));
        assert!(decision.machines.iter().all(|m|m.summary.contains("cpu=unknown")));
        assert!(validate_routing_choice("c003",None,None,&decision).is_err(),
            "aucun identifiant hors de la liste admissible");
        let frozen=serde_json::to_vec(&decision).unwrap();
        routing168_update(&state,|v|v["routing_policy"]["enabled"]=json!(false));
        let replay=routing_decision_request(&request,&receipt,&frozen_routing_plan(&receipt).unwrap()).unwrap();
        assert_eq!(serde_json::to_vec(&replay).unwrap(),frozen,
            "le snapshot de décision ne rafraîchit pas les faits");
        assert_eq!(serde_json::to_vec(&NativeDelegationRequest::AutoDelegateV2(request.clone())).unwrap(),canonical);
        assert!(state.lock().unwrap().delegation_store.tasks().unwrap().is_empty());
        assert!(rx.try_recv().is_err(),"aucun fournisseur depuis la sélection");
        drop(state);cleanup(&config);
    }

    #[test]
    fn spec221_catalogue_no_match_is_local_without_admission_or_probe() {
        let (state, config, rx, _reader, mut request, _root)=routing168_fixture(1);
        request.request_id="catalogue221".into();
        request.model=Some("PRIVATE_UNDECLARED_MODEL".into());
        let original=serde_json::to_vec(&request).unwrap();
        let mut previous=None;
        for _ in 0..2 {
            let DaemonToWrapper::NativeDelegationResult {result}=handle("conn-1",
                NativeDelegationRequest::AutoDelegateV2(request.clone()),&state)
                else {panic!("refus natif attendu")};
            assert_eq!(result["code"],"routing_candidate_unavailable");
            assert_eq!(result["detail"]["stage"],"catalogue_selection");
            assert_eq!(result["detail"]["cause"],"no_active_declared_combination");
            assert_eq!(result["detail"]["scope"],"this_admission");
            assert_eq!(result["detail"]["admission"]["state"],"not_recorded");
            assert!(result["task_id"].is_null());
            assert!(!result.to_string().contains("PRIVATE_UNDECLARED_MODEL"));
            assert!(result.to_string().len()<8192);
            assert!(result["detail"]["recovery"].as_str().unwrap().contains("fleet.options"));
            assert!(result["detail"]["human_action"].as_str().unwrap().contains("utilisateur"));
            if let Some(previous)=previous.as_ref() {assert_eq!(&result,previous)}
            previous=Some(result);
            let st=state.lock().unwrap();
            assert!(st.delegation_store.auto_admission_receipt(OWNER,&request.request_id).unwrap().is_none());
            assert!(st.delegation_store.tasks().unwrap().is_empty());
            assert!(rx.try_recv().is_err(),"aucun fournisseur ni sonde");
        }
        assert_eq!(serde_json::to_vec(&request).unwrap(),original);
        for code in ["routing_candidate_unavailable",
            "routing_candidate_unavailable:catalogue_no_match_PRIVATE",
            "routing_candidate_unavailable:PRIVATE"] {
            let result=failure(code);
            assert_eq!(result["code"],"routing_candidate_unavailable");
            assert_eq!(result["detail"]["cause"],"unobserved");
            assert!(result["detail"]["stage"].is_null());
            assert!(!result.to_string().contains("PRIVATE"));
        }
        drop(state); cleanup(&config);
    }

    #[test]
    fn spec200_auto_type_natif_nommee_sans_recu_et_canon_existant_preserve() {
        let (state, config, rx, _reader, mut request, _root) = routing168_fixture(1);
        request.request_id = "field200".into();
        request.agent_type = Some("private-profile-never-echo".into());
        let DaemonToWrapper::NativeDelegationResult { result } = handle("conn-1",
            NativeDelegationRequest::AutoDelegateV2(request.clone()), &state) else { panic!("refus natif attendu") };
        assert_eq!(result["code"], "auto_admission_invalid");
        assert_eq!(result["detail"]["field"], "agent_type");
        assert_eq!(result["detail"]["admission"]["state"], "not_recorded");
        let advice = result["detail"]["admission"]["recovery"].as_str().unwrap();
        assert!(advice.contains("corriger les paramètres avec la même request_id"));
        assert!(advice.contains("absence d’appel concurrent"));
        assert!(!advice.contains("les mêmes paramètres"));
        assert!(!advice.contains("une nouvelle request_id"));
        assert!(!result.to_string().contains("private-profile-never-echo"));
        assert!(state.lock().unwrap().delegation_store.auto_admission_receipt(OWNER, &request.request_id).unwrap().is_none());
        assert!(state.lock().unwrap().delegation_store.tasks().unwrap().is_empty());
        request.agent_type = None;
        let admitted = admit_auto_routing("conn-1", &request, None, None, None, None, &state).unwrap();
        let receipt = routing168_receipt(&state, &request);
        assert_eq!(receipt.state, AutoAdmissionState::Admitted);
        assert_eq!(receipt.task_id.as_deref(), admitted["task_id"].as_str());
        request.agent_type = Some("private-profile-never-echo".into());
        let DaemonToWrapper::NativeDelegationResult { result } = handle("conn-1",
            NativeDelegationRequest::AutoDelegateV2(request.clone()), &state) else { panic!("refus natif attendu") };
        assert_eq!(result["code"], "auto_admission_invalid");
        assert_eq!(result["detail"]["field"], "agent_type");
        assert_eq!(result["detail"]["admission"]["state"], "envelope_mismatch");
        assert_eq!(routing168_receipt(&state, &request), receipt);
        assert_eq!(state.lock().unwrap().delegation_store.tasks().unwrap().len(), 1);
        assert!(rx.try_recv().is_err());
        drop(state); cleanup(&config);
    }

    #[test]
    fn spec199_refus_de_definition_persiste_et_rejeu_sans_task() {
        use bridget_transport::protocol::LineageDecisionSourceV4;
        let (state, config, rx, _reader, request, _root) = routing168_fixture(1);
        let mut plan = routing168_plan(&state, &request);
        observe_routing_candidates("conn-1", &request, &mut plan, None, &state).unwrap();
        let receipt = {
            let st = state.lock().unwrap();
            let now = unix_timestamp();
            let receipt = routing_auto_receipt(OWNER.into(), &request,
                serde_json::to_vec(&NativeDelegationRequest::AutoDelegateV2(request.clone())).unwrap(),
                &plan, st.coordinator_epoch, now).unwrap();
            assert!(st.delegation_store.reserve_auto_admission_receipt(&receipt, now).unwrap());
            st.delegation_store.start_auto_decision_level(&receipt, receipt.coordinator_epoch,
                receipt.revision, plan.decision_level, now).unwrap()
        };
        routing168_update(&state, |v| v["agents"]["native-test"]["args"] = json!(["app-server", "--changed-definition"]));
        let code = choose_routing_admission("conn-1", &request, &plan, &receipt,
            RoutingDecisionChoice { candidate_id: "c001".into(), effort: Some("high".into()), reason: None },
            LineageDecisionSourceV4::Deterministic, None, None, None, None, &state, false).unwrap_err();
        assert_eq!(code, "routing_connection_changed:selected_probe:definition");
        let closed = routing168_receipt(&state, &request);
        assert_eq!(closed.state, AutoAdmissionState::Refused);
        assert!(closed.task_id.is_none());
        assert_eq!(closed.refusal_code.as_deref(), Some(code.as_str()));
        let reopened = crate::delegation::DelegationStore::open(&config.db_path).unwrap();
        assert_eq!(reopened.auto_admission_receipt(OWNER, &request.request_id).unwrap().unwrap(), closed);
        assert!(reopened.tasks().unwrap().is_empty());
        let replay = admit_auto_routing("conn-1", &request, None, None, None, None, &state).unwrap_err();
        assert_eq!(replay, code);
        assert_eq!(failure(&replay)["code"], "routing_connection_changed");
        assert_eq!(failure(&replay)["detail"]["changes"], json!(["definition"]));
        assert!(rx.try_recv().is_err());
        drop(reopened); drop(state); cleanup(&config);
    }

