    #[test]
    fn spec199_causes_fermees_et_ancien_refus_inconnu() {
        let proof = routing_change_error("selected_probe", &[
            ("definition", true), ("permissions", true), ("worker_epoch", true),
            ("mapping", true), ("project", true),
        ]).unwrap();
        assert!(proof.len() <= 128);
        assert_eq!(auto_terminal_refusal_code(&proof), Some(proof.as_str()));
        let projected = failure(&proof);
        assert_eq!(projected["code"], "routing_connection_changed");
        assert_eq!(projected["detail"]["changes"], json!(["definition", "permissions", "worker_epoch", "mapping", "project"]));
        assert_eq!(projected["detail"]["checks"].as_array().unwrap().len(), 5);
        assert_eq!(routing_change_error("selected_probe", &[("worker_epoch", false)]), None);
        let old = failure("routing_connection_changed");
        assert_eq!(old["detail"]["stage"], "unobserved");
        assert_eq!(old["detail"]["changes"], json!([]));
        assert!(old["detail"]["recovery"].as_str().unwrap().contains("historique"));
        for invalid in ["routing_connection_changed:selected_probe:private-secret", "routing_connection_changed:selected_probe:definition,definition", "routing_connection_changed:foreign:definition"] {
            assert!(routing_change_detail(invalid).is_none());
            assert_eq!(auto_terminal_refusal_code(invalid), Some("routing_connection_changed"));
            let view = failure(invalid);
            assert_eq!(view["code"], "routing_connection_changed");
            assert_eq!(view["detail"]["stage"], "unobserved");
            assert!(!view.to_string().contains("private-secret"));
        }
    }

    #[test]
    fn spec199_chaque_categorie_validee_produit_un_refus_sans_panique() {
        for field in ["definition", "permissions", "worker_epoch", "mapping", "project",
            "protocol", "canonical", "effort", "machine", "profile", "model", "base"] {
            let code = format!("routing_connection_changed:delegate_contract:{field}");
            assert!(routing_change_detail(&code).is_some());
            let refusal = failure(&code);
            assert_eq!(refusal["code"], "routing_connection_changed");
            assert_eq!(refusal["detail"]["changes"], json!([field]));
            assert_eq!(refusal["detail"]["checks"][0]["field"], field);
            assert!(!refusal["detail"]["checks"][0]["recovery"].as_str().unwrap().is_empty());
            assert!(!refusal["detail"]["checks"][0]["recovery"].as_str().unwrap().contains("pas reconnu"));
        }
    }

    #[test]
    fn spec199_premier_diagnostic_gagne_le_cas_de_cloture() {
        let (state, config, _rx, _reader, request, _root) = routing168_fixture(1);
        let mut plan = routing168_plan(&state, &request);
        observe_routing_candidates("conn-1", &request, &mut plan, None, &state).unwrap();
        let st = state.lock().unwrap();
        let now = unix_timestamp();
        let receipt = routing_auto_receipt(OWNER.into(), &request,
            serde_json::to_vec(&NativeDelegationRequest::AutoDelegateV2(request.clone())).unwrap(),
            &plan, st.coordinator_epoch, now).unwrap();
        assert!(st.delegation_store.reserve_auto_admission_receipt(&receipt, now).unwrap());
        let first = "routing_connection_changed:selected_probe:worker_epoch".to_owned();
        assert_eq!(close_auto_admission_error(&st, &receipt, first.clone()).unwrap(), first);
        let other = "routing_connection_changed:selected_probe:permissions".to_owned();
        assert_eq!(close_auto_admission_error(&st, &receipt, other).unwrap(), first);
        let closed = st.delegation_store.auto_admission_receipt(OWNER, &request.request_id).unwrap().unwrap();
        assert_eq!(closed.canonical, receipt.canonical);
        assert_eq!(closed.metadata, receipt.metadata);
        assert!(closed.task_id.is_none());
        assert_eq!(auto_refusal_error(&closed), first);
        drop(st); drop(state); cleanup(&config);
    }

    fn routing168_receipt(
        state: &Arc<Mutex<DaemonState>>,
        request: &AutoDelegateV2,
    ) -> AutoAdmissionReceipt {
        let st = state.lock().unwrap();
        st.delegation_store
            .auto_admission_receipt(OWNER, &request.request_id)
            .unwrap()
            .unwrap()
    }

    #[test]
    fn incident171_routing_probe_refusals_reach_client_without_admission() {
        use bridget_transport::protocol::*;
        let (state, config, rx, _reader, mut request, root) = routing168_fixture(3);
        {
            let mut st=state.lock().unwrap();
            st.host="coordinator171".into();
            st.presences.get_mut("instance-1").unwrap().host="coordinator171".into();
        }
        request.request_id = "probe171-refused".into();
        request.project_id = Some("project171".into());
        request.machine_id = Some("cartae".into());
        request.engine = Some("codex".into());
        let host = state.lock().unwrap().host.clone();
        let fingerprint = format!("{:x}", sha2::Sha256::digest(b"worker171-fixture"));
        routing168_update(&state, |value| {
            value["routing_policy"]["connections"][0]["machine_id"] = json!("cartae");
            value["routing_policy"]["machine_policies"]["cartae"] = json!({"enabled":true});
            value["machines"] = json!({"cartae":{"enabled":true,"worker_id":"worker171",
                "provisioning_revision":1,"credential_fingerprint":fingerprint,
                "allowed_agent_types":["native-test"],"mappings":{"project171":{
                    "source_host":host,"source_root":request.cwd,
                    "remote_root":root.join("remote171"),"expected_git_identity":"fixture171",
                    "mapping_revision":1}}}});
        });
        let (writer, mut reader) = super::super::presence_tests::control_socket("probe171-refused");
        {
            let mut st = state.lock().unwrap();
            st.connections.insert("worker171".into(), writer);
            st.peer_uids.insert("worker171".into(), bridget_transport::fsutil::effective_uid());
        }
        assert!(matches!(handle_worker_message(&state, "worker171",
            WrapperToDaemon::WorkerHelloWithCapabilities { hello: WorkerHelloWithCapabilities {
                hello: WorkerHello { version: REMOTE_WORKER_VERSION,
                    identity: WorkerIdentity { machine_id:"cartae".into(),
                        worker_id:"worker171".into(),provisioning_revision:1 },
                    credential: IdentityCredential::new("worker171-fixture".into()),
                    build:"fixture171".into(),capability:ClientCapability::RemoteWorkerV1 },
                capabilities:vec![WorkerCapability::CandidateProbeV2] } }),
            Some(DaemonToWrapper::WorkerAcceptedWithCapabilities { .. })));
        let responder_state = Arc::clone(&state);
        let responder = std::thread::spawn(move || {
            let frame = super::super::presence_tests::read_control(&mut reader);
            let DaemonToWrapper::CandidateProbeV2 { probe } = frame else {
                panic!("only the existing probe is expected");
            };
            assert_eq!(probe.candidates.len(), 3);
            let correlation = probe.correlation_id.clone();
            let admission = probe.admission_id.clone();
            let now = unix_timestamp();
            let reasons = [CandidateProbeRefusal::MappingUnavailable,
                CandidateProbeRefusal::PermissionsChanged, CandidateProbeRefusal::WorkspaceUnavailable];
            let result = CandidateProbeV2Result { tool_observations:Vec::new(), version:WORKER_CANDIDATE_PROBE_V2_VERSION,
                correlation_id:probe.correlation_id,connection_epoch:probe.connection_epoch,
                worker:probe.worker,admission_id:probe.admission_id,policy_revision:probe.policy_revision,
                resources:HostResourceSnapshotV1 { source_observed_at:now,received_at:now,
                    cpu_percent:None,available_memory_percent:None,normalized_load_percent:None,
                    compilation_slots:None },
                verdicts:probe.candidates.into_iter().zip(reasons).map(|(candidate,reason)|
                    CandidateProbeV2Verdict::Ineligible { candidate_id:candidate.candidate_id,reason }).collect() };
            assert!(handle_worker_message(&responder_state,"worker171",
                WrapperToDaemon::CandidateProbeResultV2 { result }).is_none());
            (correlation,admission)
        });
        let mut plan = routing168_plan(&state, &request);
        let mut selected_plan = plan.clone();
        selected_plan.observations = vec![RoutingCandidateObservation { model_option_account:None,
            definition_digest:"a".repeat(64), permission_digest:"b".repeat(64),
            mapping_revision:Some(1), project_id:Some("project171".into()),
            connection_epoch:"fixture".into(), observed_at:unix_timestamp(), received_at:unix_timestamp(),
        }; selected_plan.candidates.len()];
        assert_eq!(observe_routing_candidates("conn-1", &request, &mut plan, None, &state)
            .unwrap_err(), "routing_candidate_unavailable");
        let (correlation,admission) = responder.join().unwrap();
        // Incident186 : la relecture finale doit garder le motif du worker.
        state.lock().unwrap().remote_workers.clear();
        let error = refresh_routing_selected("conn-1",&request,&selected_plan,0,
            selected_plan.candidates[0].default_effort.as_deref(),None,&state,false).unwrap_err();
        let reread = failure(&error);
        assert_eq!(reread["code"], "routing_candidate_unavailable");
        assert_eq!(reread["detail"]["reasons"], json!([
            {"kind":"worker","code":"worker_unavailable","candidates":1}
        ]));
        assert!(auto_terminal_refusal_code(&error).is_none(), "la même admission reste réconciliable");
        assert!(plan.candidates.is_empty());
        assert_eq!(plan.decision_notes.len(), 3);
        for (index,note) in plan.decision_notes.iter().enumerate() {
            assert!(note.len() <= MAX_ROUTING_PROBE_REFUSAL_NOTE_BYTES);
            let value:Value = serde_json::from_str(note).unwrap();
            assert_eq!(value.as_object().unwrap().len(), 7);
            assert_eq!(value["machine_id"],"cartae");
            assert_eq!(value["correlation_id"], correlation);
            assert_eq!(value["admission_id"], admission);
            assert_eq!(value["candidate_id"], routing_candidate_id(index));
            assert_eq!(value["code"], ["mapping_unavailable","permissions_changed",
                "workspace_unavailable"][index]);
        }
        {
            let st = state.lock().unwrap();
            assert!(st.delegation_store.auto_admission_receipt(OWNER,&request.request_id)
                .unwrap().is_none());
            assert!(st.delegation_store.tasks().unwrap().is_empty());
        }
        assert!(rx.try_recv().is_err());
        let refused = routing_probe_failure(&plan);
        assert_eq!(refused["status"], "refused");
        assert_eq!(refused["code"], "routing_candidate_unavailable");
        assert_eq!(refused["detail"]["message"], refused["message"]);
        assert!(refused["detail"]["recovery"].as_str().unwrap().contains("detail.admission"));
        assert_eq!(refused["detail"]["reasons"], json!([
            {"kind":"candidate","code":"mapping_unavailable","candidates":1},
            {"kind":"candidate","code":"permissions_changed","candidates":1},
            {"kind":"candidate","code":"workspace_unavailable","candidates":1}
        ]));
        let original_notes = plan.decision_notes.clone();
        plan.decision_notes.clear();
        assert!(record_routing_probe_refusal(&mut plan, &correlation, &admission, "c001",
            RoutingProbeRefusalCode::Candidate(CandidateProbeRefusal::WorkspaceLimit)));
        let limit = routing_probe_failure(&plan);
        let reason = &limit["detail"]["reasons"][0];
        assert_eq!(reason["code"], "workspace_limit");
        assert!(reason["message"].as_str().unwrap().contains("lecteur historique"));
        assert!(reason["message"].as_str().unwrap().contains("imbriqués"));
        assert!(reason["recovery"].as_str().unwrap().contains("rejouer la même enveloppe"));
        assert!(reason["recovery"].as_str().unwrap().contains("Aucun nettoyage ni rejeu automatique"));
        plan.decision_notes = original_notes;
        plan.decision_notes.push(json!({"event":"routing_probe_refused","kind":"worker","code":"SECRET /private/path"}).to_string());
        assert_eq!(routing_probe_failure(&plan), refused);
        plan.decision_notes.pop();
        let before = plan.decision_notes.clone();
        assert!(!record_routing_probe_refusal(&mut plan, "opaque secret", &admission, "c001",
            RoutingProbeRefusalCode::Candidate(CandidateProbeRefusal::InvalidRequest)));
        assert!(!record_routing_probe_refusal(&mut plan, &correlation, &"x".repeat(513), "c001",
            RoutingProbeRefusalCode::Candidate(CandidateProbeRefusal::InvalidRequest)));
        assert!(!record_routing_probe_refusal(&mut plan, &correlation, &admission, "not-a-candidate",
            RoutingProbeRefusalCode::Candidate(CandidateProbeRefusal::InvalidRequest)));
        assert_eq!(plan.decision_notes, before);
        for _ in 0..130 {
            record_routing_probe_refusal(&mut plan, &correlation, &admission, "c001",
                RoutingProbeRefusalCode::Worker(WorkerRefusal::WorkerUnavailable));
        }
        assert_eq!(plan.decision_notes.len(), MAX_ROUTING_PROBE_REFUSAL_NOTES);
        let last:Value = serde_json::from_str(plan.decision_notes.last().unwrap()).unwrap();
        assert_eq!(last["kind"], "worker");
        assert_eq!(last["code"], "worker_unavailable");
        drop(state);
        cleanup(&config);
    }

    #[test]
    fn spec221_probe_targets_keep_machine_without_new_probe_or_private_text() {
        use bridget_transport::protocol::*;
        let (state,config,_rx,_reader,request,_root)=routing168_fixture(3);
        let mut plan=routing168_plan(&state,&request);
        plan.candidates[0].machine_id="cartae".into();
        plan.candidates[1].machine_id="monordinateur".into();
        let before=serde_json::to_value(state.lock().unwrap().delegation_store.tasks().unwrap()).unwrap();
        let correlation=Uuid::new_v4().to_string();
        let admission=format!("a-{}","a".repeat(32));
        assert!(record_routing_probe_refusal(&mut plan,&correlation,&admission,"c001",
            RoutingProbeRefusalCode::Candidate(CandidateProbeRefusal::WorkspaceDiverged)));
        assert!(record_routing_probe_refusal(&mut plan,&correlation,&admission,"c002",
            RoutingProbeRefusalCode::Candidate(CandidateProbeRefusal::CapabilityUnavailable)));
        let view=routing_probe_failure(&plan);
        let targets=view["detail"]["probe_targets"].as_array().unwrap();
        assert_eq!(targets.len(),2);
        assert_eq!(targets[0]["machine_id"],"cartae");
        assert_eq!(targets[1]["machine_id"],"monordinateur");
        let encoded=routing_probe_error(&plan,"routing_candidate_unavailable".into());
        let replay=failure(&encoded);
        assert_eq!(replay["detail"]["probe_targets"],view["detail"]["probe_targets"]);
        assert_eq!(replay["detail"]["reasons"],view["detail"]["reasons"]);
        assert_eq!(replay["code"],"routing_candidate_unavailable");
        assert!(auto_terminal_refusal_code(&encoded).is_none());
        assert!(replay["message"].as_str().unwrap().contains("aucune machine finale"));
        let mut bad=serde_json::from_str::<Value>(encoded.split_once(':').unwrap().1).unwrap();
        bad["targets"][0]["machine_id"]=json!("/PRIVATE/path");
        let refused=failure(&format!("routing_candidate_unavailable:{bad}"));
        assert!(refused["detail"]["probe_targets"].is_null());
        assert!(!refused.to_string().contains("PRIVATE"));
        bad["targets"][0]["machine_id"]=json!("cartae");bad["targets"][0]["candidates"]=json!(128);
        assert!(failure(&format!("routing_candidate_unavailable:{bad}"))["detail"]["probe_targets"].is_null());
        let codes=["mapping_unavailable","definition_unavailable","permissions_changed","workspace_unavailable",
            "workspace_dirty","workspace_busy","workspace_diverged","capability_unavailable"];
        let reasons=codes.iter().map(|code|json!({"kind":"candidate","code":code,"candidates":16})).collect::<Vec<_>>();
        let targets=(0..16).flat_map(|machine|codes.iter().map(move|code|json!({
            "machine_id":format!("{machine:02}{}","x".repeat(254)),"kind":"candidate","code":code,"candidates":1
        }))).collect::<Vec<_>>();
        let mut targets=targets;targets.sort_by(|a,b|a["machine_id"].as_str().cmp(&b["machine_id"].as_str())
            .then_with(||a["code"].as_str().cmp(&b["code"].as_str())));
        let maximal=json!({"reasons":reasons,"targets":targets});
        let encoded=maximal.to_string();assert!(encoded.len()>16384 && encoded.len()<=65536);
        let full=failure(&format!("routing_candidate_unavailable:{encoded}"));
        assert_eq!(full["detail"]["probe_targets"].as_array().unwrap().len(),128);
        let mut duplicate=maximal.clone();duplicate["targets"][1]=duplicate["targets"][0].clone();
        assert!(failure(&format!("routing_candidate_unavailable:{duplicate}"))["detail"]["probe_targets"].is_null());
        let mut unknown=maximal.clone();unknown["targets"][0]["code"]=json!("PRIVATE_CODE");
        let unknown=failure(&format!("routing_candidate_unavailable:{unknown}"));
        assert!(unknown["detail"]["probe_targets"].is_null());assert!(!unknown.to_string().contains("PRIVATE_CODE"));
        let too_big=format!("{}{}",encoded," ".repeat(65536));
        assert!(failure(&format!("routing_candidate_unavailable:{too_big}"))["detail"]["probe_targets"].is_null());
        let after=serde_json::to_value(state.lock().unwrap().delegation_store.tasks().unwrap()).unwrap();
        assert_eq!(before,after);
        drop(state);cleanup(&config);
    }

