    #[test]
    fn spec224_project_preparation_link_refusal_names_only_the_failed_check() {
        let view = failure("project_preparation_link_missing");
        assert_eq!(view, origin_attestation_refusal("project_preparation_link_missing"));
        assert_eq!(view["code"], "project_preparation_link_missing");
        assert_eq!(view["detail"]["cause"], "project_preparation_link_missing");
        assert_eq!(view["detail"]["scope"], "this_project_preparation");
        assert_eq!(view["detail"]["verification"], "origin_project_preparation_link");
        let message = view["message"].as_str().unwrap();
        assert_eq!(view["detail"]["message"], message);
        assert!(message.starts_with("Faire comparer"));
        assert!(message.contains("n'a pas confirmé"));
        assert!(message.contains("autres travaux"));
        let recovery = view["detail"]["recovery"].as_str().unwrap();
        for text in ["admission durable", "--registry-file", "root", "namespace", "rejeu strict"] {
            assert!(recovery.contains(text), "missing {text}");
        }
        assert!(view["detail"]["human_action"].as_str().unwrap().contains("responsable Bridget"));
        assert!(view.get("task_id").is_none());
        assert!(!view.to_string().contains("/Users/"));
        assert!(!view.to_string().contains("/home/"));
    }

    #[test]
    fn spec221_origin_busy_refusal_keeps_scope_and_never_projects_private_cause() {
        for code in ["origin_worker_unavailable","origin_proof_unavailable"] {
            let view=origin_attestation_refusal(code);
            assert_eq!(view["code"],"permission_attestation_unavailable");
            assert_eq!(view["detail"]["cause"],code);
            assert_eq!(view["detail"]["scope"],"this_attestation");
            assert!(view["detail"]["recovery"].as_str().unwrap().contains("déjà être admise"));
            assert!(view["detail"]["recovery"].as_str().unwrap().contains("ne répare pas"));
        }
        let busy=origin_attestation_refusal("origin_proof_busy");
        assert_eq!(failure("origin_proof_busy"),busy);
        let prep=failure("origin_project_preparation_busy");
        assert_eq!(prep["code"],"permission_attestation_unavailable");
        assert_eq!(prep["detail"]["cause"],"origin_project_preparation_busy");
        assert_eq!(prep["detail"]["verification"],"origin_project_preparation");
        assert!(prep["detail"]["recovery"].as_str().unwrap().contains("30 s"));
        for code in ["project_preparation_source_busy","project_preparation_busy"] {
            let view=failure(code);
            assert_eq!(view["code"],code);
            assert_eq!(view["detail"]["cause"],code);
            assert_eq!(view["detail"]["verification"],"origin_project_preparation");
        }


        assert_eq!(busy["code"],"permission_attestation_unavailable");
        assert_eq!(busy["detail"]["cause"],"origin_proof_busy");
        assert!(busy["message"].as_str().unwrap().contains("cet appel"));
        assert!(busy["message"].as_str().unwrap().contains("autres travaux"));
        assert!(busy["detail"]["recovery"].as_str().unwrap().contains("admission durable"));
        assert!(busy["detail"]["human_action"].as_str().unwrap().contains("responsable"));
        let unknown=origin_attestation_refusal("PRIVATE /path");
        assert!(!unknown.to_string().contains("PRIVATE"));
        assert_ne!(unknown["detail"]["cause"],"origin_proof_busy");
        assert!(unknown.get("task_id").is_none());
    }

