    fn sqlite_supprimer_instance_150(config: &DaemonConfig, instance: &str) {
        rusqlite::Connection::open(&config.db_path)
            .unwrap()
            .execute(
                "DELETE FROM native_delegations WHERE owner_instance=?1",
                [instance],
            )
            .unwrap();
    }

