        let (mut st, config, _rx, _reader) = fixture("n150-borne");
        let modele = modele_150(&mut st);
        // 4096 arbres soldés de moins de 7 jours : l'âge ne protège plus sous pression.
        let recent = unix_timestamp() - 3600;
        semer_brut_150(
            &config,
            &modele,
            0,
            4096,
            "result_available",
            true,
            "instance-autre",
            recent - 5000,
        );
